    func testCorpusSize() {
        XCTAssertGreaterThanOrEqual(Self.ingredients.count, 150)
        XCTAssertGreaterThanOrEqual(Self.instructions.count, 60)
    }

    func testScalingMatchesKotlin() {
        for row in Self.ingredients {
            for (factor, expected) in zip(Self.factors, row.scaled) {
                XCTAssertEqual(IngredientScaler.scale(row.line, factor: factor, words: row.words), expected, "scale \(factor): \(row.line)")
            }
        }
    }

    func testConversionMatchesKotlin() {
        for row in Self.ingredients {
            XCTAssertEqual(UnitConverter.convert(row.line, system: .asWritten, includeLiquids: true, words: row.words), row.line)
            for ((system, liquids), expected) in zip(Self.systems, row.converted) {
                XCTAssertEqual(
                    UnitConverter.convert(row.line, system: system, includeLiquids: liquids, words: row.words), expected,
                    "\(system) liquids=\(liquids): \(row.line)"
                )
            }
        }
    }

    func testScaleThenConvertMatchesKotlin() {
        for row in Self.ingredients {
            XCTAssertEqual(
                IngredientRendering.render([row.line], factor: 2, system: .metric, convertLiquids: false, words: row.words),
                [row.scaledMetric], "x2 metric: \(row.line)"
            )
            XCTAssertEqual(
                IngredientRendering.render([row.line], factor: 0.5, system: .ounces, convertLiquids: true, words: row.words),
                [row.halfOunces], "x0.5 ounces: \(row.line)"
            )
        }
    }

    func testIngredientNamesMatchKotlin() {
        for row in Self.ingredients {
            XCTAssertEqual(IngredientName.of(row.line, words: row.words), row.name, "name: \(row.line)")
        }
    }

    func testGroceriesMatchKotlin() {
        for row in Self.groceries {
            XCTAssertEqual(GroceryCombiner.combine(row.lines, words: row.words), row.combined, "combine: \(row.lines)")
            XCTAssertEqual(row.lines.map { Aisles.of($0, words: row.words).key }, row.aisles, "aisles: \(row.lines)")
        }
    }

    func testPageRecipeCheckMatchesKotlin() {
        for row in Self.picks {
            XCTAssertEqual(PageRecipeCheck.find(row.page, row.picked, kind: row.kind), row.found, row.picked)
        }
    }

    func testShortStepCheckMatchesKotlin() {
        for row in Self.shortSteps {
            XCTAssertEqual(ShortStepCheck.accept(row.original, row.short, words: row.words), row.accepted, row.short)
        }
    }

    func testStepAmountsMatchKotlin() {
        for row in Self.steps {
            XCTAssertEqual(StepAmounts.marked(StepAmounts.annotate([row.step], lines: row.lines, words: row.words)[0]), row.asGiven, row.step)
            let doubled = IngredientRendering.render(row.lines, factor: 2.0, system: .metric, convertLiquids: false, words: row.words)
            XCTAssertEqual(StepAmounts.marked(StepAmounts.annotate([row.step], lines: doubled, words: row.words)[0]), row.metric, row.step)
        }
    }

    func testCalendarLinesMatchKotlin() {
        for row in Self.ics {
            XCTAssertEqual(MealPlanIcs.contentLine("SUMMARY", row.text), row.line, row.text)
        }
    }

    func testPantryMatchesKotlin() {
        for row in Self.pantry {
            let item = PantryItem(
                id: 1, name: row.name, quantity: nil, language: row.language, aisle: .other, inStock: true,
                alwaysHave: false, purchasedDay: nil, expiresDay: nil
            )
            XCTAssertEqual(PantryMatch.covered(row.line, language: row.language, pantry: [item]), row.covered, "\(row.line) / \(row.name)")
        }
    }

    func testCountBracketDecisionsMatchKotlin() {
        for row in Self.counts {
            XCTAssertEqual(IngredientScaler.needsCountDecision(row.line, words: row.words), row.asks, row.line)
            let doubled = [nil, CountBracket.total, CountBracket.each].map {
                IngredientScaler.scale(row.line, factor: 2.0, words: row.words, bracket: $0)
            }
            XCTAssertEqual(doubled, row.doubled, row.line)
        }
    }

    func testWprmIngredientsMatchKotlin() {
        for row in Self.wprms {
            XCTAssertEqual(WprmIngredients.refine(html: row.html, lines: row.lines), row.refined, row.lines.joined(separator: " | "))
        }
    }

    func testCardHeadingsMatchKotlin() {
        for row in Self.heads {
            XCTAssertEqual(CardHeadings.refine(html: row.html, lines: row.lines), row.refined, row.lines.joined(separator: " | "))
        }
    }

    func testSiteRulesMatchKotlin() {
        for row in Self.sites {
            let url = "https://www.\(row.host)/r"
            XCTAssertEqual(SiteRules.ingredients(html: row.html, url: url, lines: row.lines), row.refined, row.host)
            XCTAssertEqual(SiteRules.steps(url: url, steps: row.steps), row.refinedSteps, row.host)
        }
    }

    func testCloseNamesMatchKotlin() {
        for row in Self.closes {
            XCTAssertEqual(DecisionCandidates.close(row.a, row.b, words: row.words), row.close, "\(row.a) / \(row.b)")
        }
    }

    func testNameCutsMatchKotlin() {
        for row in Self.nameCuts {
            XCTAssertEqual(GroceryDecisions.nameQuestion(row.line, words: row.words) != nil, row.ask, row.line)
            let split = GroceryDecisions.nameSplit(row.line, name: row.name, words: row.words)
            XCTAssertEqual(split?.core, row.core, "\(row.line) / \(row.name)")
            XCTAssertEqual(split?.trailing, row.trailing, "\(row.line) / \(row.name)")
        }
    }

    func testTrailingTextMatchesKotlin() {
        for row in Self.trails {
            let split = GroceryDecisions.split(row.line, words: row.words)
            XCTAssertEqual(split?.core, row.core, row.line)
            XCTAssertEqual(split?.trailing, row.trailing, row.line)
        }
    }

    func testTemperaturesMatchKotlin() {
        for row in Self.instructions {
            XCTAssertEqual(TemperatureConverter.convert(row.line, unit: .asWritten, words: row.words), row.line)
            XCTAssertEqual(TemperatureConverter.convert(row.line, unit: .celsius, words: row.words), row.celsius, "C: \(row.line)")
            XCTAssertEqual(TemperatureConverter.convert(row.line, unit: .fahrenheit, words: row.words), row.fahrenheit, "F: \(row.line)")
        }
    }

    func testStepTimersMatchKotlin() {
        for row in Self.instructions {
            XCTAssertEqual(StepTimers.parse(row.line, words: row.words), row.timer, "timer: \(row.line)")
        }
        for (seconds, clock, label) in Self.clocks {
            XCTAssertEqual(StepTimers.clock(seconds), clock, "clock \(seconds)")
            XCTAssertEqual(StepTimers.label(seconds), label, "label \(seconds)")
        }
    }

    func testFormattingMatchesKotlin() {
        for (value, fraction, metric) in Self.formats {
            XCTAssertEqual(IngredientScaler.format(value), fraction, "format \(value)")
            XCTAssertEqual(IngredientScaler.formatMetric(value), metric, "formatMetric \(value)")
        }
    }

    func testStripHtmlMatchesJsoup() {
        for (raw, expected) in Self.html {
            XCTAssertEqual(JsonLdRecipeParser.stripHtml(raw), expected, "stripHtml: \(raw)")
        }
    }

    func testServingsMatchKotlin() {
        for (text, parsed, bare) in Self.yields {
            XCTAssertEqual(Servings.parse(text), parsed, "parse: \(text)")
            XCTAssertEqual(Servings.bareCount(text), bare, "bareCount: \(text)")
        }
    }

    func testUrlCleanerAndInputMatchKotlin() {
        for (raw, expected) in Self.urls { XCTAssertEqual(UrlCleaner.clean(raw), expected, "clean: \(raw)") }
        for (raw, expected) in Self.inputs { XCTAssertEqual(UrlInput.normalize(raw), expected, "normalize: \(raw)") }
    }

    func testJsonLdMatchesKotlin() {
        for (label, blocks, expected) in Self.jsonLd {
            // These rows predate the recipe's language (#14), and the expected values are
            // never hand-edited, so it is left out here; LanguageWordsTests (and Kotlin's
            // RecipeLanguageTest) pin how it is chosen.
            var parsed = JsonLdRecipeParser.parse(blocks, sourceUrl: "https://src/\(label)")
            parsed?.language = nil
            XCTAssertEqual(parsed, expected, label)
        }
    }
}
